from datetime import datetime
from typing import Dict


class _Appointment:
    def __init__(
        self,
        appointment_id: int,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
    ) -> None:
        self.id = appointment_id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: Dict[int, _Appointment] = {}

    def book(
        self,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        now: datetime,
    ) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start >= end:
            raise ValueError("Start time must be strictly before end time.")

        if start < now:
            raise ValueError("Cannot book an appointment in the past.")

        # Check if patient already has an upcoming appointment relative to `now`
        for appt in self._appointments.values():
            if appt.patient == patient and appt.start >= now:
                raise ValueError(
                    f"Patient '{patient}' already has an upcoming appointment."
                )

        # Check if doctor is free during the requested interval
        if not self.is_free(doctor, start, end):
            raise ValueError(
                f"Doctor '{doctor}' is not available during the requested time."
            )

        appointment_id = self._next_id
        self._next_id += 1
        self._appointments[appointment_id] = _Appointment(
            appointment_id, patient, doctor, start, end
        )
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an appointment."""
        if appointment_id not in self._appointments:
            raise KeyError(f"Appointment ID {appointment_id} does not exist.")
        del self._appointments[appointment_id]

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            raise ValueError("Start time must be strictly before end time.")

        for appt in self._appointments.values():
            if appt.doctor == doctor:
                # Two intervals [start, end) and [appt.start, appt.end) overlap
                # if start < appt.end and end > appt.start.
                if max(start, appt.start) < min(end, appt.end):
                    return False

        return True
